const POINTS_PER_SPHINX = 1;
const BONUS_TYPE_THRESHOLD = 3;
const POINTS_PER_BONUS_TYPE = 2;
const POINTS_WITHOUT_BONUS = 1;

const isSphinx = (card: Card): boolean => card.monster === "sphinx";

const countMonsterTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const scoreForOneSphinx = (otherMonsterTypes: number): number =>
  POINTS_PER_SPHINX +
  (otherMonsterTypes > BONUS_TYPE_THRESHOLD
    ? POINTS_PER_BONUS_TYPE * (otherMonsterTypes - BONUS_TYPE_THRESHOLD)
    : POINTS_WITHOUT_BONUS);

export const scoreArmy = (army: Card[]): number =>
  army.reduce((score, card, index) => {
    if (!isSphinx(card)) return score;
    const otherCards = army.filter((_, other) => other !== index);
    return score + scoreForOneSphinx(countMonsterTypes(otherCards));
  }, 0);

